import { Fragment, type ReactNode } from "react"

import {
  GitHubAvatar,
  LineCounts,
  ListView,
  ListViewItem,
  ListViewSectionBody,
  ListViewSectionHeader,
} from "@/components"
import { AgentBadge } from "@/components/AgentBadge"
import { formatDisplayDate, toLocalDateString } from "@/lib/date"
import { formatModel } from "@/lib/model"

import type { SessionInfo } from "../api"
import { buildSessionHref } from "../urls"

export interface CommitListCheckpoint {
  checkpointId: string
  sessions: SessionInfo[]
}

export interface CommitListCommit {
  commitSha: string
  commitSubject: string | null
  commitDate: string | null
  commitAuthorUsername: string | null
  additions: number | null
  deletions: number | null
  filesChanged: number | null
  statsPending?: boolean
  fileStats: unknown[] | null
  checkpoints?: CommitListCheckpoint[]
}

interface TypedDayGroup<TCommit extends CommitListCommit> {
  date: string
  displayDate: string
  commits: (TCommit & { _index: number })[]
}

function groupByDay<TCommit extends CommitListCommit>(
  commits: TCommit[],
): TypedDayGroup<TCommit>[] {
  const groups = new Map<string, TypedDayGroup<TCommit>>()
  commits.forEach((commit, index) => {
    const date = commit.commitDate ? toLocalDateString(commit.commitDate) : "unknown"
    let group = groups.get(date)
    if (!group) {
      group = {
        date,
        displayDate: date === "unknown" ? "Unknown Date" : formatDisplayDate(date),
        commits: [],
      }
      groups.set(date, group)
    }
    group.commits.push({ ...commit, _index: index })
  })
  return Array.from(groups.values())
}

export interface CommitListProps<TCommit extends CommitListCommit = CommitListCommit> {
  commits: TCommit[]
  org?: string
  repo?: string
  getCommitHref?: (commit: TCommit) => string
  getSessionHref?: (
    commit: TCommit,
    checkpoint: CommitListCheckpoint,
    session: SessionInfo,
  ) => string | undefined
  renderCommitMeta?: (commit: TCommit) => ReactNode
  showAvatar?: boolean
}

export function CommitList<TCommit extends CommitListCommit = CommitListCommit>({
  commits,
  org,
  repo,
  getCommitHref,
  getSessionHref,
  renderCommitMeta,
  showAvatar = true,
}: CommitListProps<TCommit>) {
  const dayGroups = groupByDay(commits)
  const itemCount = commits.reduce(
    (count, commit) =>
      count +
      1 +
      (commit.checkpoints ?? []).reduce(
        (sessionCount, checkpoint) => sessionCount + checkpoint.sessions.length,
        0,
      ),
    0,
  )
  let itemIndex = 0

  return (
    <ListView itemCount={itemCount} aria-label="Commits" className="@container">
      {dayGroups.map((group) => (
        <li key={group.date} role="presentation" className="list-none">
          <ListViewSectionHeader>
            <span className="text-sm font-semibold text-default">{group.displayDate}</span>
            <span className="font-mono text-xs text-muted">
              {group.commits.length} commit
              {group.commits.length !== 1 ? "s" : ""}
            </span>
          </ListViewSectionHeader>
          <ListViewSectionBody>
            <ul role="presentation" className="m-0 list-none p-0">
              {group.commits.map((commit) => {
                const checkpoints = commit.checkpoints ?? []
                const sessions = checkpoints.flatMap((checkpoint) =>
                  checkpoint.sessions.map((session) => ({
                    ...session,
                    checkpoint,
                    checkpointId: checkpoint.checkpointId,
                  })),
                )
                const statsPending = commit.statsPending === true
                const hasLineStats =
                  !statsPending && (commit.additions != null || commit.deletions != null)
                const fileCount = statsPending
                  ? null
                  : (commit.filesChanged ?? commit.fileStats?.length ?? null)
                const lineStatsLabel = hasLineStats
                  ? `${commit.additions ?? 0} additions, ${commit.deletions ?? 0} deletions`
                  : "line stats pending"
                const fileStatsLabel =
                  fileCount == null
                    ? "file stats pending"
                    : `${fileCount} ${fileCount === 1 ? "file" : "files"}`
                const commitTitle = commit.commitSubject ?? "Untitled commit"
                const commitIndex = itemIndex++

                return (
                  <Fragment key={commit.commitSha}>
                    <ListViewItem
                      index={commitIndex}
                      href={
                        getCommitHref
                          ? getCommitHref(commit)
                          : `/gh/${encodeURIComponent(org ?? "")}/${encodeURIComponent(repo ?? "")}/commit/${encodeURIComponent(commit.commitSha)}`
                      }
                      className="flex flex-wrap items-center gap-x-2.5 gap-y-0 px-4 py-3 list-hover-transition hover:bg-hover md:h-12 md:flex-nowrap md:py-0"
                      aria-label={`${commitTitle}, ${lineStatsLabel}, ${fileStatsLabel}, by ${commit.commitAuthorUsername ?? "unknown author"}`}
                    >
                      <span className="w-14 shrink-0 font-mono text-xs text-muted">
                        {commit.commitSha.slice(0, 7)}
                      </span>
                      <span className="min-w-0 truncate text-sm font-semibold text-default">
                        {commitTitle}
                      </span>
                      {renderCommitMeta?.(commit)}
                      <span className="flex basis-full items-center justify-start gap-5 font-mono text-xs text-muted md:ml-auto md:shrink-0 md:basis-auto md:justify-end">
                        <span className="shrink-0 md:w-24 md:text-right">
                          {hasLineStats ? (
                            <LineCounts
                              additions={commit.additions ?? 0}
                              deletions={commit.deletions ?? 0}
                            />
                          ) : (
                            <span>stats pending</span>
                          )}
                        </span>
                        <span className="shrink-0 md:w-20 md:text-right">{fileStatsLabel}</span>
                        {showAvatar && (
                          <GitHubAvatar
                            username={commit.commitAuthorUsername ?? undefined}
                            className="size-5"
                          />
                        )}
                      </span>
                    </ListViewItem>
                    {sessions.length > 0 && (
                      <li role="presentation" className="list-none">
                        <ul role="presentation" className="m-0 list-none p-0">
                          {sessions.map((session, sessionIndex) => {
                            const prompt = session.prompt?.trim()
                            const title = session.prompt_redacted
                              ? "Session prompt hidden"
                              : prompt || "Untitled session"
                            const modelLabel = formatModel(session.model)
                            const defaultSessionHref = buildSessionHref(
                              org,
                              repo,
                              session,
                              session.checkpoint,
                            )
                            const sessionHref =
                              getSessionHref?.(commit, session.checkpoint, session) ??
                              defaultSessionHref
                            const sessionListIndex = itemIndex++

                            // Each session row intentionally renders the same standalone L connector.
                            // Do not extend non-last rows to `before:h-full`: that creates a continuous
                            // pipe between sibling session rows, which makes subsequent rows look nested
                            // under the first rather than aligned as separate sub-items.
                            const connectorClassName =
                              "relative h-12 w-5 shrink-0 self-stretch before:absolute before:left-0.5 before:top-0 before:h-[calc(50%-0.5rem)] before:border-l before:border-muted/30 after:absolute after:left-0.5 after:top-1/2 after:h-2 after:w-3.5 after:-translate-y-full after:rounded-bl-[3px] after:border-b after:border-l after:border-muted/30"

                            return (
                              <ListViewItem
                                key={`${session.checkpointId}-${session.sessionId ?? sessionIndex}`}
                                index={sessionListIndex}
                                href={sessionHref}
                                className="flex flex-wrap items-center gap-x-2.5 gap-y-0 px-4 py-3 list-hover-transition hover:bg-hover md:h-12 md:flex-nowrap md:py-0"
                                aria-label={`Open ${title} session at checkpoint ${session.checkpointId}`}
                              >
                                <span aria-hidden className="w-14 shrink-0" />
                                <span aria-hidden className={connectorClassName} />
                                <span className="flex min-w-0 flex-1 items-center gap-2 md:flex-initial">
                                  <AgentBadge agent={session.agent} className="shrink-0" />
                                  <span className="truncate text-sm font-semibold text-default">
                                    {title}
                                  </span>
                                </span>
                                <span aria-hidden className="basis-full md:hidden" />
                                <span className="flex items-center justify-start gap-5 font-mono text-xs text-muted md:ml-auto md:shrink-0 md:justify-end">
                                  <span
                                    className="shrink-0 md:w-24 md:truncate md:text-right"
                                    title={modelLabel || undefined}
                                    aria-hidden={modelLabel ? undefined : true}
                                  >
                                    {modelLabel ?? ""}
                                  </span>
                                  <span className="shrink-0 md:w-20 md:text-right">
                                    {session.steps} step{session.steps === 1 ? "" : "s"}
                                  </span>
                                  {showAvatar && <span aria-hidden className="size-5 shrink-0" />}
                                </span>
                              </ListViewItem>
                            )
                          })}
                        </ul>
                      </li>
                    )}
                  </Fragment>
                )
              })}
            </ul>
          </ListViewSectionBody>
        </li>
      ))}
    </ListView>
  )
}

import { request } from "@/lib/api"

export interface CommitInfo {
  commitSha: string
  commitMessage: string | null
  commitSubject: string | null
  commitBody: string | null
  commitAuthor: string | null
  commitAuthorUsername: string | null
  commitDate: string | null
  additions: number | null
  deletions: number | null
  filesChanged: number | null
  /** True when compare stats are still awaiting DB enrichment. */
  statsPending?: boolean
  filesTouched: string[] | null
  fileStats: FileStats[] | null
  url: string | null
  checkpoints: CheckpointInfo[]
}

export interface RepoCommitsResponse {
  commits: CommitInfo[]
  repo_full_name: string
  updated_at: string
  from_cache: boolean
  app_has_access: boolean | null
  session_branch_exists: boolean | null
  history_status?: "pending" | "syncing" | "complete" | "error" | null
  history_complete?: boolean
  history_pages_fetched?: number
  has_more?: boolean
  next_offset?: number | null
}

export interface ResolveCommitResponse {
  commit_sha: string
  branches: string[]
  default_branch: string | null
  suggested_branch: string | null
  commit: CommitInfo | null
  repo_full_name: string
}

export async function fetchRepoCommits(
  org: string,
  repo: string,
  branch: string = "main",
  options?: { source?: "github"; since?: string; until?: string; limit?: number; offset?: number },
): Promise<RepoCommitsResponse> {
  const params = new URLSearchParams({ branch })
  if (options?.source) {
    params.set("source", options.source)
  }
  if (options?.since) {
    params.set("since", options.since)
  }
  if (options?.until) {
    params.set("until", options.until)
  }
  if (options?.limit) {
    params.set("limit", String(options.limit))
  }
  if (options?.offset) {
    params.set("offset", String(options.offset))
  }
  return request<RepoCommitsResponse>(`/api/v1/cache/${org}/${repo}/commits?${params.toString()}`)
}

export async function resolveCommit(
  org: string,
  repo: string,
  commitSha: string,
): Promise<ResolveCommitResponse> {
  return request<ResolveCommitResponse>(
    `/api/v1/cache/${org}/${repo}/commits/resolve/${encodeURIComponent(commitSha)}`,
  )
}

export interface SessionInfo {
  prompt: string | null
  /**
   * True when `prompt` was nulled by the access-control gate (public source repo
   * with checkpoints in a separate private repo the viewer can't read).
   * Distinguishes a hidden prompt from a legitimately-null one (legacy rows,
   * empty prompts). Absent on full responses.
   */
  prompt_redacted?: boolean
  agent: string
  steps: number
  sessionId?: string
  /** Model identifier (e.g. "claude-opus-4-6"). Optional — older records may omit it. */
  model?: string
}

// Per-file stats — canonical definition lives in @/domains/platform/components/diff
import type { FileStats } from "@/domains/platform/components/diff"
export type { FileStats }

export interface CheckpointInfo {
  commitSha: string | null
  commitMessage: string | null
  commitSubject: string | null
  commitBody: string | null
  commitAuthor: string | null
  commitAuthorUsername: string | null
  commitDate: string | null
  additions: number | null
  deletions: number | null
  filesChanged: number | null
  // Per-file stats with additions/deletions breakdown
  fileStats: FileStats[] | null
  filesTouched: string[] | null
  checkpointId: string
  createdAt?: string
  sessions: SessionInfo[]
  sessionCount: number
  totalSteps: number
  agents: string[]
  // Token usage (may be null if not tracked)
  inputTokens: number | null
  outputTokens: number | null
  // Attribution data (may be null if not calculated)
  attribution: SessionAttribution | null
  // Repo where checkpoint data lives (differs from source repo for checkpoint_remote configs)
  checkpointRepoFullName: string | null
}

export interface CheckpointsResponse {
  checkpoints: CheckpointInfo[]
  repo_full_name: string
  updated_at: string
  from_cache: boolean
  app_has_access: boolean | null // null = unknown (API error)
  session_branch_exists: boolean | null // null = unknown (API error)
  history_status?: "pending" | "syncing" | "complete" | "error" | null
  history_complete?: boolean
}

export async function fetchCheckpoints(
  org: string,
  repo: string,
  branch: string = "main",
  options?: { source?: "github" },
): Promise<CheckpointsResponse> {
  const params = new URLSearchParams({ branch })
  if (options?.source) {
    params.set("source", options.source)
  }
  return request<CheckpointsResponse>(
    `/api/v1/cache/${org}/${repo}/checkpoints?${params.toString()}`,
  )
}

export interface CheckpointStatusResponse {
  app_has_access: boolean | null
  session_branch_exists: boolean | null
  checkpoint_count: number
  // False when the source repo is public but its checkpoints live in a separate
  // private repo and the viewer isn't a member. The Sessions tab and analysis
  // are hidden in this case; commit/checkpoint metadata is still visible with
  // session prompts redacted. Optional so older test mocks remain valid; the
  // server always populates it. Consumers should treat undefined as `true`
  // (default-allow during loading and against pre-flag responses).
  viewer_can_see_checkpoint_data?: boolean
}

export async function fetchCheckpointStatus(
  org: string,
  repo: string,
): Promise<CheckpointStatusResponse> {
  return request<CheckpointStatusResponse>(`/api/v1/cache/${org}/${repo}/checkpoint-status`)
}

export interface BranchesResponse {
  branches: string[]
  default_branch: string
  stored_default_branch: string
  from_cache: boolean
}

export async function fetchBranches(org: string, repo: string): Promise<BranchesResponse> {
  return request<BranchesResponse>(`/api/v1/cache/${org}/${repo}/branches`)
}

// Transcript types
export interface TranscriptImage {
  mediaType: string
  data: string // base64 encoded
}

// Tool call result metadata
export interface ToolCallResult {
  type: "text" | "error"
  file?: {
    filePath: string
    numLines?: number
  }
  matchCount?: number
  output?: string
  error?: string
  // For AskUserQuestion tool calls - the user's answers
  answers?: Record<string, string>
}

// Raw tool_use block
export interface ToolUseBlock {
  id: string
  name: string
  input: Record<string, unknown>
}

// Normalized UI annotation derived from skill-event sidecar metadata.
export interface TranscriptSkillInvocation {
  eventId?: string
  eventType: string
  skillName: string
  label?: string
  collapseTarget?: string
  defaultCollapsed?: boolean
  source?: {
    agent?: string
    signal?: string
    confidence?: string
  }
}

export interface SkillEvent {
  id?: string
  eventType: string
  skill: { name: string }
  source?: {
    agent?: string
    signal?: string
    confidence?: string
  }
  turnId?: string
  timestamp?: string
  transcriptAnchor?: {
    unit?: string
    start?: number
    end?: number
    entryIds?: string[]
    toolUseId?: string
  }
  native?: Record<string, string>
  collapse?: {
    target?: string
    label?: string
    defaultCollapsed?: boolean
  }
}

// Tool call made by the agent during a turn
export interface ToolCall extends ToolUseBlock {
  timestamp: string
  result?: ToolCallResult
  skillInvocation?: TranscriptSkillInvocation
}

export interface TranscriptRuntimeTag {
  tag:
    | "command-message"
    | "command-name"
    | "command-args"
    | "local-command-caveat"
    | "system-reminder"
  content: string
}

export interface TranscriptMessage {
  id: string
  role: "user" | "assistant"
  content: string
  images?: TranscriptImage[]
  timestamp: string
  toolCalls?: ToolCall[]
  runtimeTags?: TranscriptRuntimeTag[]
  skillInvocation?: TranscriptSkillInvocation
}

// Per-session line-level attribution
export interface SessionAttribution {
  calculatedAt: string
  agentLines: number
  humanAdded: number
  humanModified: number
  humanRemoved: number
  totalCommitted: number
  agentPercentage: number
}

export interface SessionTranscript {
  sessionId: string
  agent: string
  messages: TranscriptMessage[]
  // Transcript state at session start - used to show only relevant messages
  transcriptIdentifierAtStart: string | null
  // Line/message offset at session start - used for offset-based transcript slicing
  checkpointTranscriptStart: number | null
  // Per-session token usage (from child metadata.json)
  tokenUsage?: {
    inputTokens: number
    outputTokens: number
  }
  // Per-session line-level attribution (from child metadata.json)
  attribution?: SessionAttribution
  skillEvents?: SkillEvent[]
  // Parse quality indicators
  /** True when a native parser was not available for this agent */
  parsingFallback?: boolean
  /** Warning message when transcript parsing may be incomplete */
  parsingWarning?: string
}

export interface CompleteCheckpointTranscriptResponse {
  status?: "complete"
  checkpointId: string
  sessions: SessionTranscript[]
  from_cache?: boolean
}

export interface PendingCheckpointTranscriptResponse {
  status: "pending"
  checkpointId: string
}

export interface FailedCheckpointTranscriptResponse {
  status: "failed"
  checkpointId: string
}

export type CheckpointTranscriptResponse =
  | CompleteCheckpointTranscriptResponse
  | PendingCheckpointTranscriptResponse
  | FailedCheckpointTranscriptResponse

export async function fetchCheckpointTranscript(
  org: string,
  repo: string,
  checkpointId: string,
): Promise<CheckpointTranscriptResponse> {
  return request<CheckpointTranscriptResponse>(
    `/api/v1/cache/${org}/${repo}/checkpoints/${encodeURIComponent(checkpointId)}/transcript`,
  )
}

export interface SessionTranscriptCheckpoint {
  checkpointId: string
  commitSha: string
  message: string
  additions: number
  deletions: number
  filesChanged: number
  timestamp: string
  authorUsername: string | null
}

export interface CompleteSessionTranscriptResponse {
  status?: "complete"
  sessionId: string
  sessions: SessionTranscript[]
  from_cache?: boolean
  repo: {
    owner: string
    name: string
    fullName: string
    defaultBranch: string
    isPrivate: boolean
    publicSharingEnabled: boolean
    /**
     * True when sharing this session would actually grant access to anyone who
     * doesn't already have it (private source, or public source with separate
     * private checkpoint storage). False when the session is already public —
     * sharing would be a no-op so the toggle should be hidden.
     * Optional for backward-compat with older test mocks; treat undefined as
     * `isPrivate` (the previous condition for showing the share dialog).
     */
    shareToggleApplicable?: boolean
  }
  session: {
    agent: string
    displayName: string
    prompt: string | null
    model: string | null
    steps: number
    checkpointCount: number
    createdAt: string | null
    isPublic: boolean
  }
  checkpoints: SessionTranscriptCheckpoint[]
  tokenUsage: { inputTokens: number; outputTokens: number }
  viewer: {
    canEdit: boolean
    /**
     * False when the source repo is public but its checkpoints live in a
     * separate private repo the viewer can't read. Source-repo write access
     * doesn't imply the right to share — sharing would 403 on POST. Optional
     * for backward-compat; consumers default-allow when undefined.
     */
    canSeeCheckpointData?: boolean
  }
}

export interface PendingSessionTranscriptResponse {
  status: "pending"
  sessionId: string
}

export interface FailedSessionTranscriptResponse {
  status: "failed"
  sessionId: string
}

export type SessionTranscriptResponse =
  | CompleteSessionTranscriptResponse
  | PendingSessionTranscriptResponse
  | FailedSessionTranscriptResponse

export async function fetchSessionTranscript(
  org: string,
  repo: string,
  sessionId: string,
): Promise<SessionTranscriptResponse> {
  return request<SessionTranscriptResponse>(
    `/api/v1/cache/${org}/${repo}/session/${encodeURIComponent(sessionId)}/transcript`,
  )
}

// Resolve checkpoint location - finds which branches a checkpoint exists on
// Used when the original branch has been deleted (e.g., after PR merge)
export interface CheckpointResolveResponse {
  checkpoint_id: string
  branches: string[]
  default_branch: string | null
  suggested_branch: string
  needs_redirect: boolean
  requested_branch: string | null
  checkpoint: CheckpointInfo | null
  repo_full_name: string
}

export async function resolveCheckpoint(
  org: string,
  repo: string,
  checkpointId: string,
  requestedBranch?: string,
): Promise<CheckpointResolveResponse> {
  const params = requestedBranch ? `?branch=${encodeURIComponent(requestedBranch)}` : ""
  return request<CheckpointResolveResponse>(
    `/api/v1/cache/${org}/${repo}/checkpoints/resolve/${encodeURIComponent(checkpointId)}${params}`,
  )
}

export type { CheckpointAnalysis } from "./types/checkpointAnalysis"
import type { CheckpointAnalysis } from "./types/checkpointAnalysis"

export type CheckpointAnalysisResponse =
  | (CheckpointAnalysis & { status: "complete" })
  | { status: "pending" }
  | { status: "generating" }
  | { status: "failed"; error?: string }
  | { status: "not_available" }

export async function fetchCheckpointAnalysis(
  org: string,
  repo: string,
  checkpointId: string,
): Promise<CheckpointAnalysisResponse> {
  return request<CheckpointAnalysisResponse>(
    `/api/v1/cache/${org}/${repo}/checkpoints/${encodeURIComponent(checkpointId)}/analysis`,
  )
}

export interface SearchMeta {
  matchType: "semantic" | "keyword" | "both"
  score: number
  summary?: string
}

export interface SearchCheckpointsResponse extends CheckpointsResponse {
  searchMeta?: Record<string, SearchMeta>
}

export async function searchCheckpoints(
  org: string,
  repo: string,
  query: string,
  branch?: string,
): Promise<SearchCheckpointsResponse> {
  const { globalSearchQuery } = await import("@/domains/platform/search/api")
  const response = await globalSearchQuery({
    q: query,
    types: ["checkpoints"],
    repo: `${org}/${repo}`,
    branch,
    limit: 50,
  })

  const checkpoints: CheckpointInfo[] = []
  const searchMeta: Record<string, SearchMeta> = {}

  for (const result of response.results) {
    if (result.type !== "checkpoint") continue
    const cp = result.data
    checkpoints.push({
      commitSha: cp.commitSha ?? "",
      commitMessage: cp.commitMessage,
      commitSubject: cp.commitSubject,
      // Search response doesn't expose commit body; only subject is indexed.
      commitBody: null,
      commitAuthor: cp.author,
      commitAuthorUsername: cp.authorUsername ?? "",
      commitDate: cp.createdAt,
      additions: 0,
      deletions: 0,
      filesChanged: cp.filesTouched?.length ?? null,
      fileStats: null,
      filesTouched: cp.filesTouched,
      checkpointId: cp.id,
      sessions: [],
      sessionCount: 0,
      totalSteps: 0,
      agents: [],
      inputTokens: null,
      outputTokens: null,
      attribution: null,
      checkpointRepoFullName: null,
    })
    searchMeta[cp.id] = result.searchMeta
  }

  return {
    checkpoints,
    repo_full_name: `${org}/${repo}`,
    updated_at: new Date().toISOString(),
    from_cache: false,
    app_has_access: true,
    session_branch_exists: true,
    searchMeta,
  }
}

/**
 * Parse a CommittedMetadata JSON into a SessionInfo object
 */
export function parseSessionMetadata(
  metadataText: string,
  promptText: string | null,
): SessionInfo | null {
  try {
    const parsed: CommittedMetadata = JSON.parse(metadataText)
    const tokenUsage = parsed.token_usage
    const attribution = parsed.initial_attribution

    return {
      prompt: promptText?.split("\n")[0] ?? null,
      agent: parsed.agent ?? LEGACY_FALLBACK_AGENT_NAME,
      model: parsed.model || undefined,
      steps: parsed.checkpoints_count ?? 1,
      sessionId: parsed.session_id,
      createdAt: parsed.created_at,
      isTask: parsed.is_task,
      toolUseId: parsed.tool_use_id,
      transcriptIdentifierAtStart: parsed.transcript_identifier_at_start,
      checkpointTranscriptStart:
        parsed.checkpoint_transcript_start ?? parsed.transcript_lines_at_start,
      summary: parsed.summary,
      tokenUsage: tokenUsage
        ? {
            inputTokens: tokenUsage.input_tokens,
            cacheCreationTokens: tokenUsage.cache_creation_tokens,
            cacheReadTokens: tokenUsage.cache_read_tokens,
            outputTokens: tokenUsage.output_tokens,
            apiCallCount: tokenUsage.api_call_count,
          }
        : undefined,
      attribution: attribution ? mapAttribution(attribution) : undefined,
      // Persist an explicit empty marker for newly parsed DB rows so "no skill events"
      // is distinguishable from legacy rows parsed before the sidecar existed.
      skillEvents: normalizeSkillEvents(parsed.skill_events) ?? [],
    }
  } catch {
    return null
  }
}

/**
 * Aggregate multiple SessionInfo objects into a single SessionData
 * Used for v1 format where each checkpoint has multiple sessions
 */
export function aggregateSessionsToSessionData(
  sessions: SessionInfo[],
  rootSummary: CheckpointSummary | null,
  branch: string | null,
): SessionData {
  if (sessions.length === 0) {
    return createDefaultSessionData()
  }

  // Latest session (last in array) is used for agent, prompt, summary
  const latestSession = sessions[sessions.length - 1]

  // Sum token usage across all sessions
  let inputTokens = 0
  let cacheCreationTokens = 0
  let cacheReadTokens = 0
  let outputTokens = 0
  let apiCallCount = 0
  let hasTokenUsage = false

  for (const session of sessions) {
    if (session.tokenUsage) {
      hasTokenUsage = true
      inputTokens += session.tokenUsage.inputTokens ?? 0
      cacheCreationTokens += session.tokenUsage.cacheCreationTokens ?? 0
      cacheReadTokens += session.tokenUsage.cacheReadTokens ?? 0
      outputTokens += session.tokenUsage.outputTokens ?? 0
      apiCallCount += session.tokenUsage.apiCallCount ?? 0
    }
  }

  // Multi-session checkpoints aggregate attribution across all sessions into combined_attribution.
  // Prefer it so that token counts and percentages reflect the full checkpoint, not just the final
  // session. Fall back to the latest session's attribution for single-session checkpoints, which
  // never populate combined_attribution, and for old checkpoints written before this field existed.
  const resolvedAttribution = rootSummary?.combined_attribution
    ? mapAttribution(rootSummary.combined_attribution)
    : latestSession.attribution

  // Calculate total steps across all sessions
  const totalSteps = sessions.reduce((sum, s) => sum + (s.steps ?? 1), 0)

  return {
    prompt: latestSession.prompt,
    agent: latestSession.agent,
    model: latestSession.model ?? null,
    steps: totalSteps,
    sessionCount: sessions.length,
    strategy: rootSummary?.strategy ?? null,
    createdAt: sessions[0].createdAt ?? new Date().toISOString(),
    branch,
    sessionId: latestSession.sessionId ?? null,
    filesTouched: rootSummary?.files_touched ?? null,
    sessionIds: sessions.map((s) => s.sessionId).filter((id): id is string => id != null),
    transcriptUuidAtStart: latestSession.transcriptIdentifierAtStart ?? null,
    transcriptLinesAtStart: latestSession.checkpointTranscriptStart ?? null,
    checkpointTranscriptStart: latestSession.checkpointTranscriptStart ?? null,
    inputTokens: hasTokenUsage ? inputTokens : null,
    cacheCreationTokens: hasTokenUsage ? cacheCreationTokens : null,
    cacheReadTokens: hasTokenUsage ? cacheReadTokens : null,
    outputTokens: hasTokenUsage ? outputTokens : null,
    apiCallCount: hasTokenUsage ? apiCallCount : null,
    attributionAgentLines: resolvedAttribution?.agentLines ?? null,
    attributionHumanAdded: resolvedAttribution?.humanAdded ?? null,
    attributionHumanModified: resolvedAttribution?.humanModified ?? null,
    attributionHumanRemoved: resolvedAttribution?.humanRemoved ?? null,
    attributionTotalCommitted: resolvedAttribution?.totalCommitted ?? null,
    attributionAgentPercentage: resolvedAttribution?.agentPercentage ?? null,
    attributionCalculatedAt: resolvedAttribution?.calculatedAt ?? null,
    sessions,
  }

  if (typeof value === "string") {
    const d = new Date(value)
    return Number.isNaN(d.getTime()) ? null : d
  }
  return null
}

function liveEntriesForSession(
  checkpoint: ContributingCheckpoint,
  sessionId: string,
): SessionInfo[] {
  return filterLiveSessions(checkpoint.sessions, checkpoint.dead_session_indices).filter(
    (entry) => entry?.sessionId === sessionId,
  )
}

export function buildSessionDisplayName(
  prompt: string | null | undefined,
  lastCommitMessage: string | null | undefined,
): string {
  const promptTitle = prompt?.trim()
  if (promptTitle) return clampSessionDisplayName(promptTitle)

  const commitTitle = parseCommitMessage(lastCommitMessage).subject?.trim()
  if (commitTitle) return clampSessionDisplayName(commitTitle)

  return "Untitled session"
}

